begin;lock table public.campaigns,public.campaign_content_entries,public.campaign_state_fragments,public.campaign_character_versions,public.official_content_entries in share row exclusive mode;do $text$ begin if(select state_revision from public.campaigns where id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd')<>1710 then raise exception 'ITEM_TEXT_CAMPAIGN_CONFLICT';end if;if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:7d468487c373342123ec2cc0' and md5(to_jsonb(t)::text)='eb95f43f02ebd2966a38c7559817ecdd')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:7d468487c373342123ec2cc0';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_f754dbe1c023aca9$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Las piedras Ioun se llaman así por Ioun, un dios del conocimiento y la profecía adorado en algunos mundos. Existen muchos tipos de piedras Ioun, cada uno de ellos con una combinación distinta de forma y color.\n\nCuando utilices una acción para lanzar una de estas piedras al aire, la piedra girará alrededor de tu cabeza a una distancia de 1d3 × 30 cm y te otorgará un beneficio. A partir de entonces, otra criatura deberá utilizar una acción para agarrar o atrapar la piedra y separarla de ti, ya sea superando una tirada de ataque contra una CA de 24 o una prueba de Destreza (Acrobacias) con CD 24. Puedes utilizar una acción para tomar y guardar la piedra, lo que pone fin a su efecto.\n\nUna piedra tiene una CA de 24, 10 puntos de golpe y resistencia a todo el daño. Se considera un objeto vestido mientras gira alrededor de tu cabeza.\n\nMaestría (legendaria). Mientras este prisma verde pálido gire alrededor de tu cabeza, tu bonificador por competencia aumenta en 1.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_f754dbe1c023aca9$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:7d468487c373342123ec2cc0';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:7e70af915a0f0151f102d0a1' and md5(to_jsonb(t)::text)='3e1786e8bf11149c0ed8e4f71389531f')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:7e70af915a0f0151f102d0a1';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_569cb37696c7d3eb$"Objeto · Precio base · Peso\nHerramientas de cartógrafo · 15 po · 6 lb\n\nHerramientas de artesano. Estas herramientas especiales consisten en los objetos necesarios para llevar a cabo las tareas propias de un oficio. La tabla muestra ejemplos de las herramientas más habituales que proporcionan los útiles apropiados para una profesión concreta. La competencia con las herramientas de un oficio te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dichas herramientas, siempre y cuando las emplees en tareas de la profesión correspondiente. Cada tipo de herramientas de artesano requiere su propia competencia independiente.\n\nLas herramientas te permiten realizar algo que de otra forma estaría fuera de tu alcance, como fabricar o reparar un objeto, falsificar un documento o forzar una cerradura. Tu raza, clase, trasfondo o dotes pueden hacerte competente con ciertas herramientas. La competencia con una herramienta te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dicha herramienta. Hay que tener en cuenta que el uso de herramientas no está atado a una única característica, ya que la competencia con ellas representa un conocimiento amplio sobre su empleo. De este modo, tu GM podría pedirte que realices una prueba de Destreza para tallar detalles delicados con unas herramientas de ebanista, mientras que esculpir algo a partir de una madera especialmente dura podría requerir una prueba de Fuerza.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_569cb37696c7d3eb$::jsonb,true),'{features}',$text_2b2bca0e5c7a5789$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Herramientas de artesano. Estas herramientas especiales consisten en los objetos necesarios para llevar a cabo las tareas propias de un oficio. La tabla muestra ejemplos de las herramientas más habituales que proporcionan los útiles apropiados para una profesión concreta. La competencia con las herramientas de un oficio te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dichas herramientas, siempre y cuando las emplees en tareas de la profesión correspondiente. Cada tipo de herramientas de artesano requiere su propia competencia independiente.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_2b2bca0e5c7a5789$::jsonb,true),'{rules,definition,description}',$text_08ae83fa509ef72d$[{"id":"official-table","rows":[["Herramientas de cartógrafo","15 po","6 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Herramientas de artesano. Estas herramientas especiales consisten en los objetos necesarios para llevar a cabo las tareas propias de un oficio. La tabla muestra ejemplos de las herramientas más habituales que proporcionan los útiles apropiados para una profesión concreta. La competencia con las herramientas de un oficio te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dichas herramientas, siempre y cuando las emplees en tareas de la profesión correspondiente. Cada tipo de herramientas de artesano requiere su propia competencia independiente.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"tools-context-general","text":"Las herramientas te permiten realizar algo que de otra forma estaría fuera de tu alcance, como fabricar o reparar un objeto, falsificar un documento o forzar una cerradura. Tu raza, clase, trasfondo o dotes pueden hacerte competente con ciertas herramientas. La competencia con una herramienta te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dicha herramienta. Hay que tener en cuenta que el uso de herramientas no está atado a una única característica, ya que la competencia con ellas representa un conocimiento amplio sobre su empleo. De este modo, tu GM podría pedirte que realices una prueba de Destreza para tallar detalles delicados con unas herramientas de ebanista, mientras que esculpir algo a partir de una madera especialmente dura podría requerir una prueba de Fuerza.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-tools-context"],"provenance":"official-spanish"}]$text_08ae83fa509ef72d$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_ee76d66ef5f1117d$["official-table","official-rules-0","tools-context-general"]$text_ee76d66ef5f1117d$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:7e70af915a0f0151f102d0a1';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:7ed1857c411cd63b4a9ae3ec' and md5(to_jsonb(t)::text)='362deb08f67723ca2f3c629deb126c4d')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:7ed1857c411cd63b4a9ae3ec';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(payload,'{features}',$text_4543b46f281f3b43$[{"id":"vicious-natural-20","kind":"other","name":"Daño adicional con un 20 natural","uses":null,"order":0,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"7"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_4543b46f281f3b43$::jsonb,true),'{rules,definition,description}',$text_3bd2fbd4a29a4876$[{"id":"official-base-table","rows":[["Ballesta ligera","25 po","5 lb","1d8 perforante","+0","Munición, Recarga, A dos manos","80/320"]],"type":"table","columns":["Objeto base","Precio del objeto mundano","Peso","Daño base","Bonificación mágica al ataque","Propiedades","Alcance normal/largo (pies)"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"property-ammunition","text":"Munición. Solo puedes realizar un ataque a distancia usando un arma con esta propiedad si tienes munición para ella. Cada vez que hagas un ataque, gastarás una unidad de munición. Extraer la munición de una aljaba, un estuche u otro contenedor forma parte del ataque (necesitas una mano libre para cargar un arma a una mano). Al final del combate, podrás recuperar la mitad de la munición usada si dedicas un minuto a buscar en el campo de batalla. Si empleas un arma con esta propiedad para hacer un ataque cuerpo a cuerpo, se considerará un arma improvisada (consulta “Armas improvisadas” en esta misma sección). Además, una honda deberá estar cargada para hacer daño cuando se utilice de esta forma.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"property-loading","text":"Recarga. Debido al tiempo que requiere recargar un arma con esta propiedad, cuando utilices una acción, acción adicional o reacción para atacar con ella, solo podrás disparar una unidad de munición, incluso aunque normalmente pudieras hacer más de un ataque.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"property-two-handed","text":"A dos manos. Estas armas requieren el uso de las dos manos.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"family-rule","text":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.","type":"paragraph","section":"rules","sourceIds":["dmg-2014-vicious"],"provenance":"reviewed-translation"}]$text_3bd2fbd4a29a4876$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_62229fa2c2080f2d$["official-base-table","property-ammunition","property-loading","property-two-handed","family-rule"]$text_62229fa2c2080f2d$::jsonb?id),jsonb_build_array('official-base-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:7ed1857c411cd63b4a9ae3ec';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:7f88e7a006665acd21818ae9' and md5(to_jsonb(t)::text)='0ffe7993b27bab2052619fe5db76c156')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:7f88e7a006665acd21818ae9';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_94f1895779fee577$[{"id":"mundane-assisted-use","kind":"other","name":"Contenido del paquete","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Paquete de explorador de mazmorras (12 po). Incluye una mochila, una palanqueta, un martillo, 10 pitones, 10 antorchas, un yesquero, raciones para 10 días y una cantimplora. Además, el paquete tiene una cuerda de cáñamo de 15 m enganchada en un lado.\n\nDuración: Según su uso..","showInActions":false}]$text_94f1895779fee577$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:7f88e7a006665acd21818ae9';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:7fee756c80e074dd2dc47947' and md5(to_jsonb(t)::text)='6cade089cee13dd3bebf7cbcc3056189')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:7fee756c80e074dd2dc47947';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_bb33c31630364152$[{"id":"legacy-bonus-0","kind":"passive","name":"PassivePerception","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Otorga una bonificación de +5 a la Percepción Pasiva mientras se usa y está sintonizado.","showInActions":false},{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":1,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Estas lentes de cristal cubren los ojos. Mientras las lleves puestas, tendrás ventaja en las pruebas de Sabiduría (Percepción) que dependan de la vista. En condiciones de buena visibilidad, podrás ver detalles de criaturas y objetos muy lejanos de incluso 60 cm de diámetro.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_bb33c31630364152$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:7fee756c80e074dd2dc47947';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:81d0edc3f74b29c0545f788e' and md5(to_jsonb(t)::text)='142c483026515b6cdccddb9be7ad3c92')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:81d0edc3f74b29c0545f788e';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_4ca76cc6ddf1af62$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Tienes resistencia a un tipo de daño mientras lleves esta armadura. Tu GM elige el tipo o lo determina al azar de entre las opciones que hay a continuación.\n\n1 · Ácido · 6 · Psíquico\n2 · Frío · 7 · Radiante\n3 · Fuego · 8 · Relámpago\n4 · Fuerza · 9 · Trueno\n5 · Necrótico · 10 · Veneno\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_4ca76cc6ddf1af62$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:81d0edc3f74b29c0545f788e';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:821a97f9c8fb63e7bd326b70' and md5(to_jsonb(t)::text)='03df97dddcd4f4a99228a1ddf21b2d79')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:821a97f9c8fb63e7bd326b70';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_f0e511db536bffb9$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Los puntos de golpe perdidos por el daño de esta arma solo pueden recuperarse mediante un descanso corto o largo, no mediante la regeneración, la magia o cualquier otro medio.\n\nUna vez por turno, cuando impactes a una criatura con un ataque usando esta arma mágica, podrás herirla. Al principio de cada turno de la criatura herida, sufrirá 1d4 de daño necrótico por cada vez que la hayas herido y luego podrá realizar una tirada de salvación de Constitución con CD 15 para acabar con el efecto de esas heridas si la supera. Como alternativa, la criatura herida u otra que se encuentre a 1,5 m o menos de ella podrá usar una acción para realizar una prueba de Sabiduría (Medicina) con CD 15 y acabar con el efecto de las heridas si la supera.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_f0e511db536bffb9$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:821a97f9c8fb63e7bd326b70';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:82bec804f111fbf655ff7dcf' and md5(to_jsonb(t)::text)='02412896a98a19eb267199a56948bbc2')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:82bec804f111fbf655ff7dcf';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_4ca76cc6ddf1af62$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Tienes resistencia a un tipo de daño mientras lleves esta armadura. Tu GM elige el tipo o lo determina al azar de entre las opciones que hay a continuación.\n\n1 · Ácido · 6 · Psíquico\n2 · Frío · 7 · Radiante\n3 · Fuego · 8 · Relámpago\n4 · Fuerza · 9 · Trueno\n5 · Necrótico · 10 · Veneno\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_4ca76cc6ddf1af62$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:82bec804f111fbf655ff7dcf';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:837132a2b546795dcbf8cd3c' and md5(to_jsonb(t)::text)='eefc99dd312a3b7132d845278744ab64')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:837132a2b546795dcbf8cd3c';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_7193c7266114fc5c$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves esta diadema, podrás utilizar una acción para lanzar el conjuro rayo abrasador. Cuando lleves a cabo los ataques del conjuro, tu bonificador de ataque será de +5. La diadema no puede volver a emplearse de esta manera hasta el siguiente amanecer.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_7193c7266114fc5c$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:837132a2b546795dcbf8cd3c';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:8442091e560c1191cf13f5d2' and md5(to_jsonb(t)::text)='c959d80c78923f5fae38083ea4fa9c91')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:8442091e560c1191cf13f5d2';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(payload,'{features}',$text_d21d948ae4ba094c$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este diminuto objeto parece una pluma. Existen diferentes tipos de fichas de pluma, cada uno con un efecto diferente de un solo uso. Tu GM elige el tipo de ficha o lo determina al azar.\n\n01–15 · Abanico 61–75 ·  · Bote cisne\n16–35 · Ancla 76–85 ·  · Látigo\n36–60 · Árbol 86–00 ·  · Pájaro\n\nAbanico. Si te encuentras en un bote o barco, puedes emplear una acción para tirar la ficha al aire hasta 3 m de altura. La ficha desaparecerá y un abanico gigante en movimiento ocupará su lugar. El abanico flota y crea un viento lo bastante fuerte como para henchir las velas de un barco y aumentar su velocidad en 7,5 km/h durante 8 horas. Como acción, puedes hacer que el abanico desaparezca.\n\nAncla. Puedes emplear una acción para tocar un bote o barco con la ficha. Durante las próximas 24 horas, la embarcación no podrá moverse de ninguna manera. Volver a tocarla con la ficha pone fin al efecto. Cuando acabe el efecto, la ficha desaparece.\n\nÁrbol. Debes estar al aire libre para poder usar esta ficha. Puedes emplear una acción para tocar con la ficha un espacio sin ocupar del suelo. La ficha desaparecerá y un roble no mágico ocupará su lugar. El árbol mide 18 m de alto, el diámetro de su tronco es de 1,5 m y las ramas de su copa cubren un radio de 6 m.\n\nBote cisne. Puedes emplear una acción para tocar con la ficha una masa de agua de al menos 18 m de diámetro. La ficha desaparecerá y un bote de 15 m de largo y 6 m de ancho con la forma de un cisne ocupará su lugar. El bote se autopropulsa y se desplaza por el agua a una velocidad de 9 km/h. Puedes emplear una acción mientras te encuentres en el barco para ordenarle moverse o girar hasta 90 grados. La embarcación puede transportar hasta treinta y dos criaturas Medianas o de menor tamaño. Una criatura Grande cuenta como cuatro criaturas Medianas, mientras que una criatura Enorme cuenta como nueve. El bote permanece durante 24 horas y después desaparece. Como acción, puedes hacer que el bote desaparezca.\n\nLátigo. Puedes emplear una acción para tirar la ficha a 3 m o menos de ti. La ficha desaparecerá y un látigo flotante ocupará su lugar. A continuación, podrás utilizar una acción adicional para realizar un ataque de conjuro cuerpo a cuerpo contra una criatura que esté a 3 m o menos del látigo, con un bonificador de ataque de +9. Si impacta, el objetivo recibe 1d6 + 5 de daño de fuerza.\n\nComo acción adicional durante tu turno, puedes mover el látigo hasta 6 m y repetir el ataque contra una criatura que se encuentre a 3 m o menos de ella. El látigo desaparecerá después de 1 hora, si usas una acción para hacerlo desaparecer o si estás incapaci- tado o mueres.\n\nPájaro. Puedes emplear una acción para tirar la ficha al aire a 1,5 m de altura. La ficha desaparecerá y un enorme pájaro multicolor ocupará su lugar. El pájaro tiene el perfil de un roc, pero obedece las órdenes sencillas que le des y no puede atacar. Puede transportar hasta 250 kg mientras vuela a su velocidad máxima (24 km/h y, como máximo, 216 km al día, con descansos de una hora cada 3 horas de vuelo) o 500 kg a la mitad de esa velocidad. El ave desaparece tras volar su distancia máxima durante un día o si sus puntos de golpe se reducen a 0. Como acción, puedes hacer que el pájaro desaparezca.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_d21d948ae4ba094c$::jsonb,true),'{rules,personalDescription}',$text_e30ceaaba51fd812$"Este pequeño objeto parece una pluma. Existen diferentes tipos de fichas de pluma, cada uno con un efecto de un solo uso diferente. El DM elige el tipo o lo determina al azar.\n\n01-20 - Ancla\n21-35 - Pájaro\n36-50 - Abanico\n51-65 - Barco cisne\n66-90 - Árbol\n91-00 - Látigo \nAncla. Puedes emplear una acción para tocar un bote o barco con la ficha. Durante las próximas 24 horas, la nave no podrá moverse de ninguna manera. Volver a tocarla con la ficha termina el efecto. Cuando acabe, la ficha desaparece.\n Pájaro. Puedes utilizar una acción para tirar la ficha al aire 5 pies. Desaparecerá y será sustituida por un enorme pájaro multicolor. Tiene el perfil de un roe (ver Monster Manual), pero obedece las órdenes sencillas que le des y no puede atacar. Es capaz de transportar hasta 100 libras volando a máxima velocidad (16 millas por hora, máximo de 144 millas al día, con descansos de una hora cada 3 horas de vuelo) o 1.000 libras a mitad de velocidad. El ave desaparece tras volar su distancia máxima durante un día o si sus puntos de golpe descienden a O. Puedes desconvocar al pájaro utilizando una acción. \nAbanico. Si estás en un barco o bote, puedes usar una acción para tirar la ficha al aire a 10 pies de altura. Desaparecerá, dando paso a un abanico gigante en movimiento. Este flota y crea un viento lo suficientemente fuerte como para llenar las velas del barco, aumentando su velocidad en 5 millas por hora durante 8 horas. Puedes desconvocar el abanico utilizando una acción. \nBote cisne. Puedes emplear una acción para tocar con la ficha una masa de agua de al menos 60 pies de diámetro. La ficha desaparecerá y en su lugar aparecerá un bote de 50 pies de largo y 20 de ancho con forma de cisne. El bote es autopropulsado y se mueve por el agua a una velocidad de 6 millas por hora. Puedes utilizar una acción mientras estás en el barco para ordenarle moverse o girar 90 grados. El bote puede alojar hasta 32 criaturas Medianas o de menor tamaño. Una criatura Grande cuenta como cuatro Medianas y una Enorme como nueve. El barco permanece durante 24 horas y luego se desvanece. Puedes desconvocarlo utilizando una acción. \nArbol. Debes estar al aire libre para poder usar esta ficha. Puedes emplear una acción para tocar un espacio desocupado del suelo con la ficha. Desaparecerá y en su Jugar surgirá de la nada un roble no mágico. El árbol tiene 60 pies de altura y 5 pies de diámetro y las ramas de su copa cubren 20 pies de radio. \nLátigo. Puedes utilizar una acción para tirar la ficha a un punto situado a 10 pies o menos de distancia. Desaparecerá y en su lugar flotará un látigo. Después, podrás usar una acción adicional para realizar un ataque de conjuro cuerpo a cuerpo contra una criatura que se encuentre a 10 pies del arma, con un bonificador de ataque de +9. Si impactas, el objetivo recibe 1d6 + 5 de daño de fuerza. Puedes utilizar una acción adicional en tu turno para mover el látigo hasta 20 pies y repetir el ataque contra una criatura situada a 10 pies o menos de él. El arma desaparece tras 1 hora, cuando uses tu acción para desconvocarla, o cuando quedes incapacitado o mueras."$text_e30ceaaba51fd812$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:8442091e560c1191cf13f5d2';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:844e28dd6ac8a83fb3ca8ef0' and md5(to_jsonb(t)::text)='be2c8b78bf20c5cdc21fe8a418952794')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:844e28dd6ac8a83fb3ca8ef0';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_ca5e6004250fdca5$"Objeto · Precio base · Peso\nLibro de conjuros · 50 po · 3 lb\n\nLibro de conjuros. Indispensable para los magos, un libro de conjuros es un tomo encuadernado en cuero con 100 páginas de vitela en blanco, adecuadas para escribir conjuros.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_ca5e6004250fdca5$::jsonb,true),'{features}',$text_aa29c45791edda23$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Libro de conjuros. Indispensable para los magos, un libro de conjuros es un tomo encuadernado en cuero con 100 páginas de vitela en blanco, adecuadas para escribir conjuros.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_aa29c45791edda23$::jsonb,true),'{rules,definition,description}',$text_d0cdc14ec2a16eb6$[{"id":"official-table","rows":[["Libro de conjuros","50 po","3 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Libro de conjuros. Indispensable para los magos, un libro de conjuros es un tomo encuadernado en cuero con 100 páginas de vitela en blanco, adecuadas para escribir conjuros.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"}]$text_d0cdc14ec2a16eb6$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_bb21ed74d2f9e9dc$["official-table","official-rules-0"]$text_bb21ed74d2f9e9dc$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:844e28dd6ac8a83fb3ca8ef0';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:85b343f16d824ce798cbb857' and md5(to_jsonb(t)::text)='41e36d0357aada4a1aea7929713bc168')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:85b343f16d824ce798cbb857';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_70b341cbb9386adf$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Una flecha asesina es un arma mágica diseñada para matar a un tipo concreto de criatura. Algunas son más específicas que otras. Por ejemplo, hay tanto flechas asesinas de dragones como flechas asesinas de dragones azules. Si una criatura que pertenezca al tipo, raza o grupo asociado con una flecha asesina recibe daño de ella, deberá realizar una tirada de salvación de Constitución con CD 17; sufrirá 6d10 de daño perforante adicional si la falla o la mitad del daño adicional si la supera.\n\nEn cuanto una flecha asesina inflige su daño adicional a una criatura, se vuelve una flecha no mágica.\n\nExisten otros tipos de municiones similares, como los virotes asesinos para ballestas, aunque las flechas son las más comunes.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_70b341cbb9386adf$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:85b343f16d824ce798cbb857';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:86cffac954a9cc099e37eccf' and md5(to_jsonb(t)::text)='1720f1235d8b252a9510589e924e81f4')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:86cffac954a9cc099e37eccf';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_00e28e9a737512ca$"Objeto · Precio base · Peso\nAlforjas · 4 po · 8 lb\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_00e28e9a737512ca$::jsonb,true),'{rules,definition,description}',$text_c6457c54b8f6c83d$[{"id":"official-table","rows":[["Alforjas","4 po","8 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"}]$text_c6457c54b8f6c83d$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_b507874e9dab9bc1$["official-table"]$text_b507874e9dab9bc1$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:86cffac954a9cc099e37eccf';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:886ad6ba49cfdb0b0988802e' and md5(to_jsonb(t)::text)='14d81aa119f10425573edd393a9b5966')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:886ad6ba49cfdb0b0988802e';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_092dcf440fb6551f$"Objeto · Precio base · Peso\nLibro · 25 po · 5 lb\n\nLibro. Un libro podría contener poemas, registros históricos, información perteneciente a un ámbito de conocimiento concreto, diagramas y notas sobre artilugios gnomos o prácticamente cualquier cosa que se pueda representar mediante texto o imágenes. Un libro que contenga conjuros recibe el nombre de “libro de conjuros” y se describe a continuación.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_092dcf440fb6551f$::jsonb,true),'{features}',$text_a65602c74ff050f0$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Libro. Un libro podría contener poemas, registros históricos, información perteneciente a un ámbito de conocimiento concreto, diagramas y notas sobre artilugios gnomos o prácticamente cualquier cosa que se pueda representar mediante texto o imágenes. Un libro que contenga conjuros recibe el nombre de “libro de conjuros” y se describe a continuación.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_a65602c74ff050f0$::jsonb,true),'{rules,definition,description}',$text_292b14a2b96e71ca$[{"id":"official-table","rows":[["Libro","25 po","5 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Libro. Un libro podría contener poemas, registros históricos, información perteneciente a un ámbito de conocimiento concreto, diagramas y notas sobre artilugios gnomos o prácticamente cualquier cosa que se pueda representar mediante texto o imágenes. Un libro que contenga conjuros recibe el nombre de “libro de conjuros” y se describe a continuación.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"}]$text_292b14a2b96e71ca$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_bb21ed74d2f9e9dc$["official-table","official-rules-0"]$text_bb21ed74d2f9e9dc$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:886ad6ba49cfdb0b0988802e';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:88c9115b7d543622bd1c0bde' and md5(to_jsonb(t)::text)='08f0626b086284d392fcbc73c8de4dff')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:88c9115b7d543622bd1c0bde';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(payload,'{features}',$text_eb1c1509c017f08d$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"A primera vista, este objeto parece un barril de hierro sellado Grande que pesa 250 kg. El barril tiene un pestillo escondido, que se puede encontrar si se supera una prueba de Inteligencia (Investigación) con CD 20. Si se abre el pestillo, se accede a una escotilla en un extremo del barril, en el que pueden entrar dos criaturas Medianas o más pequeñas arrastrándose. Al fondo hay diez palancas dispuestas en fila en posición neutra que pueden levantarse o bajarse. Si se usan determinadas palancas, el aparato se transforma en una especie de langosta gigante.\n\nEl aparato del crustáceo es un objeto Grande con el siguiente perfil: Clase de Armadura: 20 Puntos de golpe: 200 Velocidad: 9 m, nadar 9 m (o 0 m en ambos casos si no se han extendido las patas y cola) Inmunidad a daño: psíquico, veneno El aparato puede utilizarse como vehículo, pero requiere un piloto para ello. Mientras la escotilla esté cerrada, el compartimento es estanco y hermético. Contiene aire suficiente para respirar durante 10 horas, divididas entre el número de criaturas que necesiten respirar en su interior.\n\nEl aparato flota en el agua. También puede sumergirse a una profundidad de 270 m. Por debajo de esta profundidad, el vehículo sufre 2d6 de daño contundente por minuto debido a la presión.\n\nUna criatura que esté en el compartimento puede utilizar una acción para subir o bajar hasta dos de las palancas del aparato. Después de cada uso, la palanca regresa a su posición neutra. Cada palanca, de izquierda a derecha, funciona como se muestra en la tabla “Palancas del aparato del crustáceo”. Palancas del aparato del crustáceo\n\n1 · La cola y las patas se extienden, lo que permite que el aparato camine y nade. · Las patas y la cola se retraen, lo que reduce la velocidad del aparato a 0 e impide que se beneficie de ningún bonificador a su velocidad.\n2 · La persiana de la ventana delantera se abre. · La persiana de la ventana delantera se cierra.\n3 · Las persianas de las ventanas laterales se abren (dos por lado). · Las persianas de las ventanas laterales se cierran (dos por lado).\n4 · Se extienden dos pinzas desde la parte delantera del aparato. · Las pinzas se retraen.\n5 · Cada pinza extendida lleva a cabo el siguiente ataque con arma cuerpo a cuerpo: +8 a impactar, alcance 1,5 m, un objetivo. Impacto: 7 (2d6) de daño contundente. · Cada pinza extendida lleva a cabo el siguiente ataque con arma cuerpo a cuerpo: +8 a impactar, alcance 1,5 m, un objetivo. Impacto: El objetivo quedará agarrado (CD 15 para escapar).\n6 · El aparato camina o nada hacia delante. · El aparato camina o nada hacia atrás.\n7 · El aparato gira 90 grados a la izquierda. · El aparato gira 90 grados a la derecha.\n8 · Unas linternas con forma de ojo emiten luz brillante en un radio de 9 m y luz tenue 9 m más allá. · La luz se apaga.\n9 · El aparato desciende hasta 6 m en un medio líquido. · El aparato asciende hasta 6 m en un medio líquido.\n10 · La escotilla trasera se abre. · La escotilla trasera se cierra.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_eb1c1509c017f08d$::jsonb,true),'{rules,personalDescription}',$text_323b77af972ae710$"A primera vista, este objeto parece un barril de hierro sellado, Grande, que pesa 500 libras. Tiene un resorte escondido, que es posible encontrar teniendo éxito en una prueba de Inteligencia (Investigación) CD 20. Activar el resorte abre una escotilla en uno de los extremos del barril, permitiendo entrar arrastrándose a dos criaturas de tamaño Mediano o más pequeñas. Dentro, en el otro extremo, hay 10 palancas, todas ellas en posición neutra y que pueden ser movidas hacia arriba o hacia abajo. Cuando se pulsan ciertas palancas, el aparato se transforma hasta parecer una langosta gigante. El Aparato de Kwalish es un objeto Grande con el siguiente perfil:\n\nClase de Armadura: 20\nPuntos de golpe: 200\nVelocidad: 30 pies, 30 pies nadando (o O pies en ambos casos si no se ha n extendido patas y cola)\nInmunidad a daño: psíquico, veneno\n\nEl aparato puede ser usado como vehículo, pero para ello necesita un piloto. Mientras la escotilla esté cerrada, el compartimento es estanco y hermético. Contiene suficiente aire para respirar durante 10 horas, divididas entre el número de criaturas del interior que necesiten respirar. El aparato flota en el agua. Ta mbién puede sumergirse hasta una profundidad de 900 pies. S i desciende por debajo de ella, recibirá 2d6 de daño por minuto debido a la presión. Una criatura en el compartimento puede emplear una acción para mover hasta dos de las palancas arriba o abajo. Después de cada uso, la palanca vuelve a la posición neutra. Cada palanca, de izquierda a derecha, funciona como se muestra en la tabla palancas del Aparato de Kwalish.\n\nAparato De Kwalish Nivel\n1 - La cola y las patas se extienden, permitiendo que el aparato camine y nade. - Las patas y la cola se retraen, reduciendo la velocidad del aparato a O e impidiendo que se beneficie de ningún bonificador a su velocidad.\n2 - La persiana de la ventana delantera se abre. - La persiana de la ventana delantera se cierra.\n3 - Las persianas de las ventanas laterales se abren (dos por lado). - Las persianas de las ventanas laterales se cierran (dos por lado).\n4 - Se extienden dos garras de la parte frontal del aparato. - Se retraen las garras\n5 - Cada garra, si está extendida, hace el siguiente ataque con arma cuerpo a cuerpo: +8 a impactar, alcance 5 pies, un objetivo. Impacto: 7 (2d6) de daño contundente. - Cada garra, si está extendida, hace el siguiente ataque con arma cuerpo a cuerpo: +8 a impactar, alcance 5 pies, un objetivo. Impacto: la criatura es agarrada (CD 15 para escapar).\n6 - El aparato camina o nada hacia delante. - El aparato camina o nada hacia atrás.\n7 - El aparato gira 90 grados a la izquierda. - El aparato gira 90 grados a la derecha.\n8 - Unas linternas con forma de ojo emiten luz brillante en un radio de 30 pies y luz tenue 30 pies más allá. - La luz se apaga \n9 - El aparato desciende hasta 20 pies en un medio líquido. - El aparato asciende hasta 20 pies en un medio líquido\n10 - La escotilla trasera se abre. - La escotilla trasera se cierra.\n\nRequiere sintonización."$text_323b77af972ae710$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:88c9115b7d543622bd1c0bde';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:8a04f86771d4d29eeccaedd8' and md5(to_jsonb(t)::text)='4271fda78fbfef7245b142d23573b2b5')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:8a04f86771d4d29eeccaedd8';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_72383d98f44f666c$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"El medallón tiene 3 cargas. Mientras lo lleves puesto, podrás utilizar una acción y gastar 1 carga para lanzar el conjuro detectar pensamientos (CD de salvación 13) desde él. El medallón recupera 1d3 cargas empleadas cada día, al amanecer.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_72383d98f44f666c$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:8a04f86771d4d29eeccaedd8';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:8a0b52974feae87ab4720b0d' and md5(to_jsonb(t)::text)='69c43ad457b970687cf7b3dc279e7b32')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:8a0b52974feae87ab4720b0d';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_18e6126021f5b235$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando ataques a una criatura con esta arma mágica y saques un 20 en la tirada de ataque, el objetivo sufrirá 3d6 de daño necrótico adicional si no es un autómata o un muerto viviente. Además, obtendrás una cantidad de puntos de golpe temporales igual al daño adicional infligido.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_18e6126021f5b235$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:8a0b52974feae87ab4720b0d';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:8a613560179ce75309d54f99' and md5(to_jsonb(t)::text)='d6f44cb3490c425c8b29fd04134d25ee')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:8a613560179ce75309d54f99';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_6c180faeb5f5026f$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves puesto este colgante, te estabilizarás si estás agonizando al principio de tu turno. Además, cuando tires un Dado de Golpe para recuperar puntos de golpe, se duplicará la cantidad de puntos de golpe que recuperas.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_6c180faeb5f5026f$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:8a613560179ce75309d54f99';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:8a8fbb6b819be5eeb799cd18' and md5(to_jsonb(t)::text)='936976232cee99a63dda88f1bc7c0648')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:8a8fbb6b819be5eeb799cd18';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_e722eefe44c85638$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Obtienes 10 puntos de golpe temporales que duran 1 hora a partir del momento en que bebes esta poción. Durante ese periodo, te encontrarás bajo el efecto del conjuro bendición (no requiere concentración). Esta poción azul borbotea y echa humo como si estuviera hirviendo.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_e722eefe44c85638$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:8a8fbb6b819be5eeb799cd18';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:8aa13b5042ba0f4052b7b278' and md5(to_jsonb(t)::text)='2afdf1305e1f2b4a404092a2fe7f1b84')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:8aa13b5042ba0f4052b7b278';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_40ec8342a824c4ae$"Objeto · Precio base · Peso\nPalanqueta · 2 po · 5 lb\n\nPalanqueta. Una palanqueta te da ventaja en aquellas pruebas de Fuerza en las que resulte útil hacer palanca.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_40ec8342a824c4ae$::jsonb,true),'{features}',$text_6f1d9ea42031bbb9$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Palanqueta. Una palanqueta te da ventaja en aquellas pruebas de Fuerza en las que resulte útil hacer palanca.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_6f1d9ea42031bbb9$::jsonb,true),'{rules,definition,description}',$text_e001331f02e6f861$[{"id":"official-table","rows":[["Palanqueta","2 po","5 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Palanqueta. Una palanqueta te da ventaja en aquellas pruebas de Fuerza en las que resulte útil hacer palanca.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"}]$text_e001331f02e6f861$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_bb21ed74d2f9e9dc$["official-table","official-rules-0"]$text_bb21ed74d2f9e9dc$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:8aa13b5042ba0f4052b7b278';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:8af13bb03749f70e9339f0cb' and md5(to_jsonb(t)::text)='5df92645a5d5964b7fc4b06b67199972')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:8af13bb03749f70e9339f0cb';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_5acce8575efbd176$"Objeto · Precio base · Peso\nSuministros de alquimista · 50 po · 8 lb\n\nHerramientas de artesano. Estas herramientas especiales consisten en los objetos necesarios para llevar a cabo las tareas propias de un oficio. La tabla muestra ejemplos de las herramientas más habituales que proporcionan los útiles apropiados para una profesión concreta. La competencia con las herramientas de un oficio te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dichas herramientas, siempre y cuando las emplees en tareas de la profesión correspondiente. Cada tipo de herramientas de artesano requiere su propia competencia independiente.\n\nLas herramientas te permiten realizar algo que de otra forma estaría fuera de tu alcance, como fabricar o reparar un objeto, falsificar un documento o forzar una cerradura. Tu raza, clase, trasfondo o dotes pueden hacerte competente con ciertas herramientas. La competencia con una herramienta te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dicha herramienta. Hay que tener en cuenta que el uso de herramientas no está atado a una única característica, ya que la competencia con ellas representa un conocimiento amplio sobre su empleo. De este modo, tu GM podría pedirte que realices una prueba de Destreza para tallar detalles delicados con unas herramientas de ebanista, mientras que esculpir algo a partir de una madera especialmente dura podría requerir una prueba de Fuerza.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_5acce8575efbd176$::jsonb,true),'{features}',$text_2b2bca0e5c7a5789$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Herramientas de artesano. Estas herramientas especiales consisten en los objetos necesarios para llevar a cabo las tareas propias de un oficio. La tabla muestra ejemplos de las herramientas más habituales que proporcionan los útiles apropiados para una profesión concreta. La competencia con las herramientas de un oficio te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dichas herramientas, siempre y cuando las emplees en tareas de la profesión correspondiente. Cada tipo de herramientas de artesano requiere su propia competencia independiente.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_2b2bca0e5c7a5789$::jsonb,true),'{rules,definition,description}',$text_d771e173c4434726$[{"id":"official-table","rows":[["Suministros de alquimista","50 po","8 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Herramientas de artesano. Estas herramientas especiales consisten en los objetos necesarios para llevar a cabo las tareas propias de un oficio. La tabla muestra ejemplos de las herramientas más habituales que proporcionan los útiles apropiados para una profesión concreta. La competencia con las herramientas de un oficio te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dichas herramientas, siempre y cuando las emplees en tareas de la profesión correspondiente. Cada tipo de herramientas de artesano requiere su propia competencia independiente.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"tools-context-general","text":"Las herramientas te permiten realizar algo que de otra forma estaría fuera de tu alcance, como fabricar o reparar un objeto, falsificar un documento o forzar una cerradura. Tu raza, clase, trasfondo o dotes pueden hacerte competente con ciertas herramientas. La competencia con una herramienta te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dicha herramienta. Hay que tener en cuenta que el uso de herramientas no está atado a una única característica, ya que la competencia con ellas representa un conocimiento amplio sobre su empleo. De este modo, tu GM podría pedirte que realices una prueba de Destreza para tallar detalles delicados con unas herramientas de ebanista, mientras que esculpir algo a partir de una madera especialmente dura podría requerir una prueba de Fuerza.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-tools-context"],"provenance":"official-spanish"}]$text_d771e173c4434726$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_ee76d66ef5f1117d$["official-table","official-rules-0","tools-context-general"]$text_ee76d66ef5f1117d$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:8af13bb03749f70e9339f0cb';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:8b3fcc59e77077e00e089e90' and md5(to_jsonb(t)::text)='5b5ec4a13741667ae4b1af447d9c8f33')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:8b3fcc59e77077e00e089e90';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_cee6b0c3dbb382f1$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras empuñes esta vara, podrás utilizar una acción para activarla. Os transportará instantánea- mente a ti y hasta otras 199 criaturas voluntarias que puedas ver a un paraíso situado en un espacio extraplanar. Puedes elegir la forma que adopta este paraíso. Podría ser un plácido jardín, un claro agradable, una taberna alegre, un palacio enorme, una isla tropical, una fantástica feria o cualquier cosa que puedas imaginar. Independientemente de su naturaleza, el paraíso contiene agua y comida suficientes para sustentar a sus visitantes. Cualquier otra cosa con la que se pueda interactuar en este espacio extraplanar solo podrá existir dentro de él. Por ejemplo, una flor recogida de un jardín del paraíso desaparece si se saca fuera del espacio extraplanar.\n\nPor cada hora que un visitante pase en el paraíso, recuperará tantos puntos de golpe como si hubiera gastado 1 Dado de Golpe. Además, las criaturas no envejecen mientras se encuentran en el paraíso, aunque el tiempo transcurre con normalidad. Los visitantes pueden permanecer en el paraíso hasta 200 días divididos por el número de criaturas que haya en él (redondeando hacia abajo).\n\nCuando el tiempo se agote o utilices una acción para finalizar el efecto, todos los visitantes reaparecerán en el lugar que ocupaban cuando activaste la vara o en el espacio sin ocupar más cercano a ese lugar. La vara no podrá usarse de nuevo hasta que hayan transcurrido 10 días.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_cee6b0c3dbb382f1$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:8b3fcc59e77077e00e089e90';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:8b457fb486eaa62761e1af40' and md5(to_jsonb(t)::text)='b98616bb0c1767c9c3b6f0685171d97b')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:8b457fb486eaa62761e1af40';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_00fc3478083c3b24$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves prendido este broche, tendrás resistencia al daño de fuerza e inmunidad al daño infligido por el conjuro proyectil mágico.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_00fc3478083c3b24$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:8b457fb486eaa62761e1af40';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:8c43510ebccc077670038abb' and md5(to_jsonb(t)::text)='c62d23ed7f290ae664e6c63669d94f07')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:8c43510ebccc077670038abb';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_cd4ebcae1032608c$"Objeto · Precio base · Peso\nMartillo · 1 po · 3 lb\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_cd4ebcae1032608c$::jsonb,true),'{rules,definition,description}',$text_11072c2cd0901b4c$[{"id":"official-table","rows":[["Martillo","1 po","3 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"}]$text_11072c2cd0901b4c$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_b507874e9dab9bc1$["official-table"]$text_b507874e9dab9bc1$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:8c43510ebccc077670038abb';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:8d85de3910c02958da0b2003' and md5(to_jsonb(t)::text)='c014d45a435ff975889f0f8047ec4892')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:8d85de3910c02958da0b2003';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(payload,'{features}',$text_56cc57121c607185$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Recibes un bonificador de +2 a las tiradas de ataque y de daño que hagas con esta arma mágica.\n\nLa espada tiene 1d8 + 1 cargas. Si causas un crítico contra una criatura que tenga menos de 100 puntos de golpe, deberá superar una tirada de salvación de Constitución con CD 15 o morirá al instante, ya que el arma arrancará la fuerza vital de su cuerpo (los autómatas o los muertos vivientes son inmunes). La espada pierde 1 carga si la criatura muere. El arma pierde esta propiedad si no le quedan cargas.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_56cc57121c607185$::jsonb,true),'{rules,personalDescription}',$text_9814adb2c4b68230$"Obtienes un bonificador de +2 a las tiradas de ataque y daño realizadas con esta arma mágica.\n\nRobo de vida. El arma tiene 1d8 + 1 cargas. Cuando atacas a una criatura que tiene menos de 100 puntos de golpe con esta arma y sacas un 20 en el d20 para la tirada de ataque, la criatura debe superar una tirada de salvación de Constitución CD 15 o morirá instantáneamente cuando la espada le arranque la fuerza vital del cuerpo. Los constructos y los no muertos superan la tirada de salvación automáticamente. El arma pierde 1 carga si la criatura muere. Cuando al arma no le quedan cargas, pierde esta propiedad."$text_9814adb2c4b68230$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:8d85de3910c02958da0b2003';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:8dd6403aac77cfcf26306fda' and md5(to_jsonb(t)::text)='429e57e59a1335701a456a8a4c81656c')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:8dd6403aac77cfcf26306fda';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_78a5ae1bb2b2a52b$[{"id":"legacy-bonus-0","kind":"passive","name":"AC","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Otorga una bonificación de +2 a la CA.","showInActions":false},{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":1,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves esta armadura, obtendrás un bonificador de +2 a la CA. Además, si cualquier efecto te desplaza por el suelo contra tu voluntad, puedes usar tu reacción para reducir hasta 3 m la distancia en que te mueves.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_78a5ae1bb2b2a52b$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:8dd6403aac77cfcf26306fda';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:8e74acfe2a0c28dcf4c90bd9' and md5(to_jsonb(t)::text)='deca4fb67d354c7930c7601f3a3b3bee')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:8e74acfe2a0c28dcf4c90bd9';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(payload,'{features}',$text_4679f8b93c97527e$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta varita tiene 7 cargas para utilizar las propiedades que se describen a continuación. Recupera 1d6 + 1 cargas empleadas cada día, al amanecer. Si gastas la última carga de la varita, tira 1d20. Si el resultado es 1, la varita se convierte en cenizas y se destruye.\n\nCono de terror. Mientras empuñes la varita, podrás usar una acción y gastar 2 cargas para que la punta de la varita emita un cono de 18 m de luz ámbar. Todas las criaturas situadas en el cono deberán superar una tirada de salvación de Sabiduría con CD 15 o quedarán asustadas de ti durante 1 minuto. Una criatura asustada de esta manera deberá dedicar sus turnos a tratar de alejarse de ti todo lo que pueda y no podrá acercarse voluntariamente a ningún espacio que se encuentre a 9 m o menos de ti. Tampoco podrá llevar a cabo reacciones. Tan solo podrá realizar la acción de correr o intentar escapar de un efecto que le impida moverse. Si no tiene adónde ir, la criatura podrá usar la acción de esquivar. Al final de cada uno de sus turnos, la criatura podrá repetir la tirada de salvación y, si tiene éxito, se librará del efecto.\n\nOrden. Mientras empuñes la varita, podrás usar una acción para gastar 1 carga y ordenar a otra criatura que huya o se postre, como con el conjuro orden imperiosa (CD de salvación de conjuros 15).\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_4679f8b93c97527e$::jsonb,true),'{rules,personalDescription}',$text_9405a7aba986b76f$"Esta varita tiene 7 cargas para las siguientes propiedades. Recupera 1d6 + 1 cargas gastadas diariamente al amanecer. Si gastas la última carga de la varita, tira 1d20. Con un 1, la varita se deshace en cenizas y queda destruida.\n\nOrden. Mientras sostienes la varita, puedes usar una acción para gastar 1 carga y ordenar a otra criatura que huya o se arrastre, como con el conjuro de orden (salvación CD 15).\n\nCono de miedo. Mientras sostienes la varita, puedes usar una acción para gastar 2 cargas, lo que hace que la punta de la varita emita un cono de luz ámbar de 60 pies. Cada criatura en el cono debe tener éxito en una tirada de salvación de Sabiduría CD 15 o te tendrá miedo durante 1 minuto. Mientras esté asustada de esta manera, una criatura debe pasar sus turnos tratando de alejarse de ti lo más que pueda, y no puede moverse voluntariamente a un espacio a 30 pies o menos de ti. Tampoco puede realizar reacciones. Para su acción, solo puede usar la acción de Correr o tratar de escapar de un efecto que le impida moverse. Si no tiene ningún lugar al que moverse, la criatura puede usar la acción de Esquivar. Al final de cada uno de sus turnos, una criatura puede repetir la tirada de salvación, terminando el efecto sobre sí misma si tiene éxito."$text_9405a7aba986b76f$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:8e74acfe2a0c28dcf4c90bd9';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:8e9870158921c82b6141bae1' and md5(to_jsonb(t)::text)='0b88445d5bca07b20a2b6d17d30d8106')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:8e9870158921c82b6141bae1';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_56cdea340ebd3b00$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras calces estas botas, podrás utilizar una acción para lanzar a voluntad el conjuro levitar sobre ti.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_56cdea340ebd3b00$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:8e9870158921c82b6141bae1';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:8ec089ba90c7b3afc8bb2f17' and md5(to_jsonb(t)::text)='6aee4441eae2c69f496c893e1779aae1')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:8ec089ba90c7b3afc8bb2f17';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_0f41f81ff846d525$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta varita tiene 7 cargas. Mientras la empuñes, podrás usar una acción y gastar 1 o más de sus cargas para lanzar el conjuro bola de fuego (CD de salvación 15) desde ella. Si empleas 1 carga, podrás lanzar la versión de nivel 3 del conjuro. Puedes aumentar el nivel del espacio de conjuro en 1 por cada carga adicional que emplees.\n\nLa varita recupera 1d6 + 1 cargas empleadas cada día, al amanecer. Si gastas la última carga de la varita, tira 1d20. Si el resultado es 1, la varita se convierte en cenizas y se destruye.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_0f41f81ff846d525$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:8ec089ba90c7b3afc8bb2f17';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:8ff078f8b72ac0e9e11beaec' and md5(to_jsonb(t)::text)='a895c4aa235ef6bd858a6aec68fa6e10')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:8ff078f8b72ac0e9e11beaec';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(payload,'{features}',$text_78cacd5c998f65d7$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este anillo está vinculado a uno de los cuatro Planos Elementales. Tu GM elige el plano o lo determina al azar.\n\nMientras lo lleves puesto, tendrás ventaja en las tiradas de ataque contra elementales del plano vinculado y ellos tendrán desventaja en las tiradas de ataque contra ti. Además, tendrás acceso a ciertas propiedades en función del plano vinculado.\n\nEl anillo tiene 5 cargas. Recupera 1d4 +1 cargas empleadas cada día, al amanecer. Los conjuros lanzados desde el anillo tienen una CD de salvación de 17.\n\nAnillo de comandar elementales de agua. Puedes gastar 2 de las cargas del anillo para lanzar el conjuro dominar monstruo sobre un elemental de agua. Además, puedes permanecer de pie sobre superficies líquidas y andar por ellas como si fueran terreno firme. También puedes hablar y entender acuano.\n\nSi ayudas a matar a un elemental de agua mientras tengas sintonización con el anillo, accedes las siguientes propiedades adicionales: • Puedes respirar bajo el agua y obtienes una velocidad nadando igual a tu velocidad caminando. • Puedes lanzar los siguientes conjuros desde el anillo empleando las cargas necesarias: crear o destruir agua (1 carga), controlar agua (3 cargas), muro de hielo (3 cargas) o tormenta de hielo (2 cargas).\n\nAnillo de comandar elementales de aire. Puedes gastar 2 de las cargas del anillo para lanzar el conjuro dominar monstruo sobre un elemental de aire. Además, cuando caigas, descenderás 18 m por asalto y no sufrirás daño por la caída. También puedes hablar y entender aurano.\n\nSi ayudas a matar a un elemental de aire mientras tengas sintonización con el anillo, accedes las siguientes propiedades adicionales: • Tienes resistencia al daño de relámpago. • Tienes una velocidad volando igual a tu velocidad caminando y puedes levitar. • Puedes lanzar los siguientes conjuros desde el anillo empleando las cargas necesarias: muro de viento (1 carga), ráfaga de viento (2 cargas) o relámpago en cadena (3 cargas).\n\nAnillo de comandar elementales de fuego. Puedes gastar 2 de las cargas del anillo para lanzar el conjuro dominar monstruo sobre un elemental de fuego. Además, tienes resistencia al daño de fuego. También puedes hablar y entender ígneo.\n\nSi ayudas a matar a un elemental de fuego mientras tengas sintonización con el anillo, accedes las siguientes propiedades adicionales: • Eres inmune al daño de fuego. • Puedes lanzar los siguientes conjuros desde el anillo empleando las cargas necesarias: bola de fuego (2 cargas), manos ardientes (1 carga) o muro de fuego (3 cargas).\n\nAnillo de comandar elementales de tierra. Puedes gastar 2 de las cargas del anillo para lanzar el conjuro dominar monstruo sobre un elemental de tierra. Además, puedes moverte por terreno difícil compuesto de escombros, rocas o tierra como si fuera terreno normal. También puedes hablar y entender terrano.\n\nSi ayudas a matar a un elemental de tierra mientras tengas sintonización con el anillo, accedes las siguientes propiedades adicionales: • Tienes resistencia al daño de ácido. • Puedes moverte a través de tierra sólida o roca como si estas superficies fueran terreno difícil. Si acabas tu turno en ellas, irás a parar al espacio sin ocupar más cercano en el que estuviste por última vez. • Puedes lanzar los siguientes conjuros desde el anillo empleando las cargas necesarias: moldear la piedra (2 cargas), muro de piedra (3 cargas) o piel pétrea (3 cargas).\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_78cacd5c998f65d7$::jsonb,true),'{rules,personalDescription}',$text_d24c035476638883$"Este anillo está vinculado al Plano Elemental del Aire. Mientras lo lleves puesto, tendrás ventaja en las tiradas de ataque contra elementales del aire, y ellos tendrán desventaja en las tiradas de ataque contra ti. Además, tendrás acceso a propiedades basadas en el Plano Elemental del Aire. El anillo tiene 5 cargas. Recupera 1d4 + 1 cargas gastadas diariamente al amanecer. Los hechizos lanzados desde el anillo tienen una CD de salvación de 17. Puedes gastar 2 de las cargas del anillo para lanzar dominar monstruo sobre un elemental del aire. Además, cuando caes, desciendes 60 pies por asalto y no sufres daño por la caída. También puedes hablar y entender Auran. Si ayudas a matar a un elemental de aire mientras estás en sintonía con el anillo, obtienes acceso a las siguientes propiedades adicionales:\n\n-Tienes resistencia al daño por rayos\n-Tienes una velocidad de vuelo igual a tu velocidad al caminar y puedes flotar\n-Puedes lanzar los siguientes hechizos desde el anillo, gastando la cantidad necesaria de cargas: relámpago en cadena (3 cargas), ráfaga de viento (2 cargas) o muro de viento (1 carga)."$text_d24c035476638883$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:8ff078f8b72ac0e9e11beaec';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:8ff4129cbfb5f59e99585e4e' and md5(to_jsonb(t)::text)='43a00d23aa660d0c2f17d5f87c6cd245')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:8ff4129cbfb5f59e99585e4e';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(payload,'{features}',$text_79d15a2b9ac643a0$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Recibes un bonificador de +3 a las tiradas de ataque y de daño que hagas con esta arma mágica.\n\nLa primera vez que ataques con la espada en cada uno de tus turnos, puedes transferir parte o todo el bonificador de la espada a tu Clase de Armadura en vez de usar el bonificador en los ataques de ese turno. Por ejemplo, puedes reducir el bonificador a tus tiradas de ataque y de daño a +1 y obtener un bonificador de +2 a tu CA. Los bonificadores ajustados permanecen en vigor hasta el principio de tu siguiente turno, aunque debes empuñar la espada para aprovechar el bonificador a la CA que confiere.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_79d15a2b9ac643a0$::jsonb,true),'{rules,personalDescription}',$text_9b5d632c315d4cc9$"Obtienes un bonificador de +3 a las tiradas de ataque y daño realizadas con esta arma mágica. \nLa primera vez que ataques con la espada en cada uno de tus turnos, puedes transferir parte o la totalidad del bonificador de la espada a tu Clase de Armadura, en lugar de usar el bonificador en cualquier ataque de ese turno. Por ejemplo, podrías reducir el bonificador a tus tiradas de ataque y daño a +1 y obtener un bonificador de +2 a la CA. Los bonificadores ajustados permanecen en efecto hasta el comienzo de tu siguiente turno, aunque debes sostener la espada para obtener un bonificador a la CA de ella."$text_9b5d632c315d4cc9$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:8ff4129cbfb5f59e99585e4e';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:903dd146fa94bcb540f66067' and md5(to_jsonb(t)::text)='abc127166ec9457d3d80079cfeef24a6')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:903dd146fa94bcb540f66067';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_2958e57ce8bcfdff$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves puesto este anillo, podrás lanzar a voluntad el conjuro telequinesis, pero solo sobre objetos que no lleve o vista alguien.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_2958e57ce8bcfdff$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:903dd146fa94bcb540f66067';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:9372bf03b25b9c3b9c203e43' and md5(to_jsonb(t)::text)='61a790df4d20a93206bf1d078901b072')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:9372bf03b25b9c3b9c203e43';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_249d9877e6e0199e$[{"id":"official-2014-rule","kind":"action","name":"Beber o administrar","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando bebas esta poción, tu puntuación de Fuerza cambiará durante 1 hora. El tipo de gigante determina la puntuación (consulta la tabla más adelante). La poción no tendrá ningún efecto si tu Fuerza es igual o superior a esa puntuación.\n\nEn el líquido transparente de la poción flota un trozo de uña de un gigante del tipo correspondiente. La poción de fuerza de gigante de escarcha y la poción de fuerza de gigante de piedra tienen el mismo efecto.\n\nGigante de las colinas · 21 · Infrecuente\nGigante de escarcha/piedra · 23 · Rara\nGigante de fuego · 25 · Rara\nGigante de las nubes · 27 · Muy rara\nGigante de las tormentas · 29 · Legendaria\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":true}]$text_249d9877e6e0199e$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:9372bf03b25b9c3b9c203e43';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:93f1c99090f8be79a17fd06e' and md5(to_jsonb(t)::text)='7846033f0fda80a4100b195adcf6bc53')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:93f1c99090f8be79a17fd06e';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_438f81c3761060f9$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Estas lentes de cristal cubren los ojos. Tienen 3 cargas. Mientras las lleves puestas, como acción, podrás gastar 1 carga para lanzar el conjuro hechizar persona (CD de salvación 13) sobre un humanoide que esté a 9 m o menos de ti, pero solo si podéis veros mutuamente. Las lentes recuperan todas las cargas empleadas cada día, al amanecer.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_438f81c3761060f9$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:93f1c99090f8be79a17fd06e';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:957d1a1e835c57b5736aa511' and md5(to_jsonb(t)::text)='75cc29af2425e536408a36d3a012b114')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:957d1a1e835c57b5736aa511';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_3b1106888529a711$[{"id":"flaming-toggle","kind":"bonus-action","name":"Encender o apagar la hoja","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Puedes utilizar una acción adicional para pronunciar la palabra de activación de esta espada mágica, lo que cubrirá su hoja de llamas. Estas llamas emiten luz brillante en un radio de 12 m y luz tenue 12 m más allá. Mientras la espada esté envuelta en llamas, infligirá 2d6 de daño de fuego adicional a cualquier objetivo al que impacte. Las llamas duran hasta que utilices una acción adicional para volver a pronunciar la palabra de activación o hasta que sueltes o envaines la espada.\n\nPronunciar la palabra de activación como acción adicional. Emite luz brillante a 40 pies y tenue otros 40 pies; se apaga al soltarla, envainarla o volver a usar la palabra como acción adicional.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":true},{"id":"flaming-hit","kind":"other","name":"Daño con la hoja encendida","uses":null,"order":1,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"2d6"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Puedes utilizar una acción adicional para pronunciar la palabra de activación de esta espada mágica, lo que cubrirá su hoja de llamas. Estas llamas emiten luz brillante en un radio de 12 m y luz tenue 12 m más allá. Mientras la espada esté envuelta en llamas, infligirá 2d6 de daño de fuego adicional a cualquier objetivo al que impacte. Las llamas duran hasta que utilices una acción adicional para volver a pronunciar la palabra de activación o hasta que sueltes o envaines la espada.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_3b1106888529a711$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:957d1a1e835c57b5736aa511';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:963783ee3a520240dda29847' and md5(to_jsonb(t)::text)='cc583779eb9e1ffbed4f4e19326be68a')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:963783ee3a520240dda29847';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(payload,'{features}',$text_79d15a2b9ac643a0$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Recibes un bonificador de +3 a las tiradas de ataque y de daño que hagas con esta arma mágica.\n\nLa primera vez que ataques con la espada en cada uno de tus turnos, puedes transferir parte o todo el bonificador de la espada a tu Clase de Armadura en vez de usar el bonificador en los ataques de ese turno. Por ejemplo, puedes reducir el bonificador a tus tiradas de ataque y de daño a +1 y obtener un bonificador de +2 a tu CA. Los bonificadores ajustados permanecen en vigor hasta el principio de tu siguiente turno, aunque debes empuñar la espada para aprovechar el bonificador a la CA que confiere.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_79d15a2b9ac643a0$::jsonb,true),'{rules,personalDescription}',$text_9b5d632c315d4cc9$"Obtienes un bonificador de +3 a las tiradas de ataque y daño realizadas con esta arma mágica. \nLa primera vez que ataques con la espada en cada uno de tus turnos, puedes transferir parte o la totalidad del bonificador de la espada a tu Clase de Armadura, en lugar de usar el bonificador en cualquier ataque de ese turno. Por ejemplo, podrías reducir el bonificador a tus tiradas de ataque y daño a +1 y obtener un bonificador de +2 a la CA. Los bonificadores ajustados permanecen en efecto hasta el comienzo de tu siguiente turno, aunque debes sostener la espada para obtener un bonificador a la CA de ella."$text_9b5d632c315d4cc9$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:963783ee3a520240dda29847';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:9638893b09627d66fd5f549d' and md5(to_jsonb(t)::text)='70e0b0d7ab3b1313e695a12d57307a1f')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:9638893b09627d66fd5f549d';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_232253ce061865d6$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta varita tiene 7 cargas. Mientras la empuñes, podrás usar una acción y gastar 1 carga para pronunciar su palabra de activación. Durante el siguiente minuto, conocerás la dirección en la que se encuentra la criatura hostil más cercana a ti que esté a 18 m o menos, pero no la distancia exacta. La varita puede percibir la presencia de criaturas hostiles que sean etéreas o invisibles o estén disfrazadas o escondidas, así como las que se detecten a simple vista. El efecto acaba si dejas de empuñar la varita.\n\nLa varita recupera 1d6 + 1 cargas empleadas cada día, al amanecer. Si gastas la última carga de la varita, tira 1d20. Si el resultado es 1, la varita se convierte en cenizas y se destruye.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_232253ce061865d6$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:9638893b09627d66fd5f549d';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:96f92ffa499fc09fac85545f' and md5(to_jsonb(t)::text)='df4c8bc85248e2ef90b48c2e39c15fa1')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:96f92ffa499fc09fac85545f';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_4ca76cc6ddf1af62$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Tienes resistencia a un tipo de daño mientras lleves esta armadura. Tu GM elige el tipo o lo determina al azar de entre las opciones que hay a continuación.\n\n1 · Ácido · 6 · Psíquico\n2 · Frío · 7 · Radiante\n3 · Fuego · 8 · Relámpago\n4 · Fuerza · 9 · Trueno\n5 · Necrótico · 10 · Veneno\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_4ca76cc6ddf1af62$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:96f92ffa499fc09fac85545f';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:970e20d4fe130f423459a002' and md5(to_jsonb(t)::text)='59ce73b2f84006d2d2696e5f6b1929b3')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:970e20d4fe130f423459a002';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_6a29b2a5cb1b4fff$"Objeto · Precio base · Peso\nTienda para dos personas · 2 po · 20 lb\n\nTienda. Una lona bajo la que guarecerse, sencilla y transportable, en la que pueden dormir dos personas.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_6a29b2a5cb1b4fff$::jsonb,true),'{features}',$text_a46ddb59c1ac21a7$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Tienda. Una lona bajo la que guarecerse, sencilla y transportable, en la que pueden dormir dos personas.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_a46ddb59c1ac21a7$::jsonb,true),'{rules,definition,description}',$text_f14a0d01e36de408$[{"id":"official-table","rows":[["Tienda para dos personas","2 po","20 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Tienda. Una lona bajo la que guarecerse, sencilla y transportable, en la que pueden dormir dos personas.","type":"paragraph","section